// Bulk conflict fetches (optimization): one round trip per conflict type
// across many doctors instead of three queries per doctor. Grouped in
// memory by doctor_id, preserving candidate order for short-circuit scans.
func (q *Queries) OverlappingDoctorAppointmentsBulk(ctx context.Context, arg OverlappingDoctorAppointmentsBulkParams) ([]Appointment, error) {
	rows, err := q.db.Query(ctx, overlappingDoctorAppointmentsBulk, arg.DoctorIds, arg.NewEnd, arg.NewStart)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Appointment
	for rows.Next() {
		var i Appointment
		if err := rows.Scan(
			&i.ID,
			&i.AppointmentNumber,
			&i.PatientID,
			&i.DoctorID,
			&i.ScheduledStartAtUtc,
			&i.ScheduledEndAtUtc,
			&i.TimezoneSnapshot,
			&i.Status,
			&i.AppointmentFor,
			&i.ReasonForVisit,
			&i.ComplaintBrief,
			&i.MedicalConditions,
			&i.Allergies,
			&i.BookingProfileSnapshot,
			&i.DoctorSnapshot,
			&i.ProviderMeta,
			&i.CancelledBy,
			&i.CancelledReason,
			&i.RescheduledFromAppointmentID,
			&i.DailyRoomName,
			&i.DailyRoomUrl,
			&i.DailyRoomExpiresAt,
			&i.DailyRecordingID,
			&i.VideoStartedAt,
			&i.VideoEndedAt,
			&i.Reminder24hSentAt,
			&i.Reminder1hSentAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

